glsl.prelude:
float fcBoxDist(vec3 p, vec3 b) {
  vec3 q = abs(p) - b;
  return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

de.source:
vec3 mengerFold(vec3 p, inout float s, inout vec4 trap) {
  p = abs(p);
  if (p.x < p.y) p.xy = p.yx;
  if (p.x < p.z) p.xz = p.zx;
  if (p.y < p.z) p.yz = p.zy;
  p = p * 3.0 - vec3(2.0);
  if (p.z < -1.0) p.z += 2.0;
  s *= 3.0;
  trap = min(trap, vec4(abs(p), dot(p, p)));
  return p;
}

float de(vec3 p, inout float s, inout vec4 trap) {
  for (int i = 0; i < uIterations; i++) {
    p = mengerFold(p, s, trap);
  }
  return fcBoxDist(p, vec3(1.0));
}

material.source:
int material(vec3 p, vec3 n) {
  vec3 a = abs(n);
  if (a.y >= a.x && a.y >= a.z) return n.y > 0.0 ? 0 : 2;
  if (a.x >= a.z) return 9;
  return 11;
}
